import{_ as r,c as a,o as t,ag as i}from"./chunks/framework.C86mscM5.js";const h=JSON.parse('{"title":"Traefik","description":"","frontmatter":{},"headers":[],"relativePath":"devops/networking/traefik.md","filePath":"devops/networking/traefik.md","lastUpdated":1788689791000}'),o={name:"devops/networking/traefik.md"};function l(n,e,s,d,f,c){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="traefik" tabindex="-1"><a href="https://traefik.io/" target="_blank" rel="nofollow noopener noreferrer">Traefik</a> <a class="header-anchor" href="#traefik" aria-label="Permalink to &quot;[Traefik](https://traefik.io/)&quot;">​</a></h1><p>Traefik 是面向动态基础设施的反向代理和负载均衡器，可以从 Docker、Kubernetes 等 Provider 发现路由配置。</p><h2 id="核心模型" tabindex="-1">核心模型 <a class="header-anchor" href="#核心模型" aria-label="Permalink to &quot;核心模型&quot;">​</a></h2><ul><li><strong>EntryPoint</strong>：监听地址和端口，例如 HTTP/HTTPS。</li><li><strong>Router</strong>：根据 Host、Path 等规则匹配请求。</li><li><strong>Middleware</strong>：在转发前后执行重定向、鉴权、限流、Header 等处理。</li><li><strong>Service</strong>：定义实际后端及负载均衡方式。</li><li><strong>Provider</strong>：从文件、Docker、Kubernetes CRD/Gateway API 等来源获取配置。</li></ul><h2 id="使用建议" tabindex="-1">使用建议 <a class="header-anchor" href="#使用建议" aria-label="Permalink to &quot;使用建议&quot;">​</a></h2><ul><li>管理端 Dashboard 不直接暴露公网，启用认证和网络限制。</li><li>生产环境明确 TLS 证书存储和多副本时的协调方式。</li><li>固定镜像版本，升级前检查废弃配置与 CRD 兼容性。</li><li>为入口、路由和后端开启访问日志、指标和 Trace 关联。</li><li>Kubernetes 中优先明确选择 Ingress 或 Gateway API，避免多套入口资源并存却无人负责。</li></ul><p>参见 <a href="./traffic-routing.html">流量入口与 Gateway</a>。</p><blockquote><p>The Cloud Native Application Proxy</p></blockquote>',8)]))}const k=r(o,[["render",l]]);export{h as __pageData,k as default};
